CREATE OR REPLACE FUNCTION public.protect_campus_login_id() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF (NEW.login_id, NEW.faculty_id, NEW.faculty_subject) IS DISTINCT FROM (OLD.login_id, OLD.faculty_id, OLD.faculty_subject) AND current_user IN ('authenticated','anon') THEN RAISE EXCEPTION 'Sign-in IDs and faculty assignments must be changed by an administrator.'; END IF; RETURN NEW; END $$;